QStatusBar::item { border: none; }
QStatusBar QFrame[segment="true"] { border: none; border-left: 1px solid #3F3670; background: transparent; }
QStatusBar QLabel { color: #A9A3C9; }
QStatusBar QToolButton[role="problems"] {
    color: #F47067; border: 1px solid transparent; padding: 0 1px; margin: -1px 0;
}
QStatusBar QToolButton[role="keys"] { border: 1px solid transparent; padding: 0 1px; margin: -1px 0; }
QStatusBar QProgressBar { background: #2A2350; border: none; border-radius: 4px; }
QStatusBar QProgressBar::chunk { background: #FF8A3D; border-radius: 4px; }
QLabel#saveDot { border-radius: 4px; background: #A9A3C9; }
QLabel#saveDot[state="success"] { background: #4AC26B; }
QLabel#saveDot[state="warning"] { background: #E3B341; }
QMenuBar { background: #1F1A3A; }
QMenuBar::item:selected, QMenu::item:selected { background: #3A2350; color: #E6E8EB; }
QMenu { background: #1F1A3A; border: 1px solid #3F3670; }
QScrollBar:vertical { background: transparent; width: 12px; margin: 2px; }
QScrollBar:horizontal { background: transparent; height: 12px; margin: 2px; }
QScrollBar::handle { background: #3F3670; border-radius: 4px; min-height: 28px; min-width: 28px; }
QScrollBar::handle:hover { background: #A9A3C9; }
QScrollBar::add-line, QScrollBar::sub-line { width: 0; height: 0; }
QScrollBar::add-page, QScrollBar::sub-page { background: transparent; }
QToolTip { background: #1F1A3A; color: #E6E8EB; border: 1px solid #3F3670; padding: 4px; }
QToolButton#viewButton { padding: 4px 24px 4px 8px; }
QToolButton[role="viewTool"] { border: 1px solid transparent; border-radius: 6px; padding: 4px; }
QToolButton[role="viewTool"]:hover { background: #2A2350; }
QToolButton[role="viewTool"]:checked { background: #3A2350; }
QCheckBox:disabled { color: #A9A3C9; }
QToolButton[role="link"] {
    border: 1px solid transparent; background: transparent; color: #FF5FA2; padding: 1px 4px;
}
QToolButton[role="link"]:hover { text-decoration: underline; }
QToolButton[role="link"]:disabled { color: #A9A3C9; }
QToolButton#manageButton::menu-indicator { image: none; width: 0; }
QToolButton#viewButton::menu-indicator { subcontrol-position: right center; right: 6px; }
/* Klavye odağı: çerçeve kalınlığı sabit kalır (yalnızca renk değişir), boyut oynamaz. En sonda durur ki
   rol kurallarının `border` tanımları odak rengini ezmesin. */
QPushButton:focus, QPushButton[kind="flat"]:focus { border-color: #FF5FA2; }
QPushButton[kind="primary"]:focus { border-color: #E6E8EB; }
QToolButton[role="statusChip"]:focus, QToolButton[role="chip"]:focus, QToolButton[role="viewTool"]:focus,
QToolButton[role="link"]:focus, QStatusBar QToolButton[role="problems"]:focus,
QStatusBar QToolButton[role="keys"]:focus { border-color: #FF5FA2; }
QLineEdit:focus, QComboBox:focus, QSpinBox:focus, QPlainTextEdit:focus { border-color: #FF5FA2; }
QCheckBox::indicator:focus { border-color: #FF5FA2; }
QCheckBox::indicator:checked:focus { border-color: #E6E8EB; }
QRadioButton::indicator:focus { border-color: #FF5FA2; }
QRadioButton::indicator:checked:focus { border-color: #E6E8EB; }
